def encode(fields):
    return '|'.join(f.replace('\\', '\\\\').replace('|', '\\|') for f in fields)


def decode(line):
    fields = []
    current = []
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if ch == '\\':
            if i + 1 >= n:
                raise ValueError('trailing backslash')
            nxt = line[i + 1]
            if nxt not in ('\\', '|'):
                raise ValueError(f'invalid escape sequence: \\{nxt}')
            current.append(nxt)
            i += 2
        elif ch == '|':
            fields.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(ch)
            i += 1
    fields.append(''.join(current))
    return fields

