from codec import decode


def _parse_cents(value):
    if not value.startswith('-'):
        if not value.isdigit():
            raise ValueError(f'invalid cents: {value!r}')
    else:
        if not (len(value) > 1 and value[1:].isdigit()):
            raise ValueError(f'invalid cents: {value!r}')
    return int(value)


def summarize(lines):
    totals = {}
    seen = set()
    for line in lines:
        fields = decode(line)
        if len(fields) != 3:
            raise ValueError(f'expected 3 fields, got {len(fields)}')
        event_id, account, cents = fields
        cents_value = _parse_cents(cents)
        key = (event_id, account, cents_value)
        if key in seen:
            continue
        seen.add(key)
        totals[account] = totals.get(account, 0) + cents_value
    return totals

