import unittest
import codec
import reducer


class Smoke(unittest.TestCase):
    def test_import(self):
        import codec as c
        import reducer as r


class EncodeTests(unittest.TestCase):
    def test_plain_single_field(self):
        self.assertEqual(codec.encode(['abc']), 'abc')

    def test_plain_multiple_fields(self):
        self.assertEqual(codec.encode(['a', 'b', 'c']), 'a|b|c')

    def test_roundtrip_unicode_and_empty(self):
        fields = ['', 'héllo ünïcode', '', '中文|tést\\']
        self.assertEqual(codec.decode(codec.encode(fields)), fields)

    def test_escapes_backslash(self):
        self.assertEqual(codec.encode(['a\\b']), 'a\\\\b')

    def test_escapes_pipe(self):
        self.assertEqual(codec.encode(['x|y']), 'x\\|y')

    def test_does_not_mutate_input(self):
        fields = ['a|b', 'c\\d', 'plain']
        snapshot = list(fields)
        codec.encode(fields)
        self.assertEqual(fields, snapshot)


class DecodeTests(unittest.TestCase):
    def test_empty_line_decodes_to_single_empty_field(self):
        self.assertEqual(codec.decode(''), [''])

    def test_plain_line(self):
        self.assertEqual(codec.decode('a|b|c'), ['a', 'b', 'c'])

    def test_empty_fields_are_preserved(self):
        self.assertEqual(codec.decode('|a|'), ['', 'a', ''])

    def test_decodes_escaped_pipe(self):
        self.assertEqual(codec.decode('x\\|y'), ['x|y'])

    def test_decodes_escaped_backslash(self):
        self.assertEqual(codec.decode('a\\\\b'), ['a\\b'])

    def test_escaped_pipe_is_not_a_separator(self):
        result = codec.decode('\\|')
        self.assertEqual(result, ['|'])

    def test_roundtrip(self):
        for fields in (['x'], ['', ''], ['\\', '|', 'a|b\\c']):
            self.assertEqual(codec.decode(codec.encode(fields)), fields)

    def test_each_character_type_is_a_field(self):
        self.assertEqual(codec.decode('\\\\|\\||é|'), ['\\', '|', 'é', ''])

    def test_trailing_backslash_raises(self):
        with self.assertRaises(ValueError):
            codec.decode('abc\\')

    def test_single_trailing_backslash_raises(self):
        with self.assertRaises(ValueError):
            codec.decode('\\')

    def test_invalid_escape_raises(self):
        for bad in ('a\\q', '\\n', 'x\\ty'):
            with self.assertRaises(ValueError):
                codec.decode(bad)

    def test_escape_in_later_field_raises(self):
        with self.assertRaises(ValueError):
            codec.decode('a|b\\c|d')


class SummarizeTests(unittest.TestCase):
    def test_empty_input_returns_empty_dict(self):
        self.assertEqual(reducer.summarize([]), {})

    def test_simple_sums(self):
        lines = ['1|checking|100', '2|checking|-40', '3|savings|25']
        self.assertEqual(
            reducer.summarize(lines), {'checking': 60, 'savings': 25})

    def test_zero_total_is_retained(self):
        self.assertEqual(reducer.summarize(['1|a|5', '2|a|-5']), {'a': 0})

    def test_exact_retransmission_counts_once(self):
        lines = ['1|a|100', '2|b|50', '1|a|100', '3|a|100']
        self.assertEqual(reducer.summarize(lines), {'a': 200, 'b': 50})

    def test_full_duplicate_line_counts_once(self):
        self.assertEqual(reducer.summarize(['1|a|0', '1|a|0']), {'a': 0})

    def test_same_id_same_account_same_cents_once(self):
        self.assertEqual(reducer.summarize(['9|a|-7', '9|a|-7']), {'a': -7})

    def test_conflicting_duplicate_id_raises(self):
        with self.assertRaises(ValueError):
            reducer.summarize(['1|a|100', '1|b|100'])

    def test_conflicting_duplicate_id_different_cents_raises(self):
        with self.assertRaises(ValueError):
            reducer.summarize(['1|a|100', '1|a|50'])

    def test_conflicting_id_after_retransmission_raises(self):
        with self.assertRaises(ValueError):
            reducer.summarize(['1|a|100', '1|a|100', '1|a|50'])

    def test_leading_zeros_are_valid(self):
        self.assertEqual(reducer.summarize(['1|a|007']), {'a': 7})

    def test_negative_leading_zeros_are_valid(self):
        self.assertEqual(reducer.summarize(['1|a|-007']), {'a': -7})

    def test_zero_negative_zero(self):
        self.assertEqual(reducer.summarize(['1|a|0', '2|a|-0']), {'a': 0})

    def test_plus_sign_is_rejected(self):
        for cents in ('+1', '+-1', '+0'):
            with self.assertRaises(ValueError):
                reducer.summarize(['1|a|' + cents])

    def test_non_numeric_cents_rejected(self):
        for cents in ('', '-', '1.5', '1,000', ' 1', '5 ', '-5x', '--5', '١٢'):
            with self.assertRaises(ValueError):
                reducer.summarize(['1|a|' + cents])

    def test_wrong_field_count_rejected(self):
        for line in ('', 'a|b', 'a|b|c|d', '|');
            with self.assertRaises(ValueError):
                reducer.summarize([line])

    def test_malformed_encoding_rejected(self):
        for line in ('1|a|5\\', '1|a|5\\q', '1|a\\', '1\\a|5'):
            with self.assertRaises(ValueError):
                reducer.summarize([line])

    def test_malformed_first_field_rejected(self):
